const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {pathToFileURL}=require('node:url');const {chromium}=require(process.env.SCIMUX_E2E_PLAYWRIGHT);
(async()=>{const source=process.argv[2],out=process.argv[3];fs.mkdirSync(out,{recursive:true,mode:0o700});const {guestMessageHTML}=await import(pathToFileURL(path.join(source,'web/js/team-guest.js')));const key=['a'.repeat(32),'b'.repeat(32),'c'.repeat(16),'d'.repeat(16)].join('/');const file={id:'0123456789abcdef',sha256:'e'.repeat(64),size:9,name:'synthetic.txt',mime:'text/plain'};const entry={seq:1,anchor:0,author:'b'.repeat(32),at:'2026-01-01T00:00:00Z',text:'Synthetic file',attachments:[file],_peopleRetained:{[file.id]:false}};const markup=guestMessageHTML(entry,{},'a'.repeat(32),{},'', '',key,p=>p);const links=fs.readFileSync(path.join(source,'web/index.html'),'utf8').match(/<link rel="stylesheet" href="[^"]+">/g).join('\n');const server=http.createServer((req,res)=>{const name=new URL(req.url,'http://fixture').pathname;if(name==='/'){res.setHeader('Content-Type','text/html');res.end(`<!doctype html><html><head>${links}</head><body><section id="chat" style="display:flex"><div id="msgwrap"><div id="msgs">${markup}</div></div></section><script>window.clicks=0;document.addEventListener('click',e=>{e.preventDefault();if(e.target.closest('a'))window.clicks++})</script></body></html>`);return;}if(/^\/css\/[a-z-]+\.css$/.test(name)){res.setHeader('Content-Type','text/css');res.end(fs.readFileSync(path.join(source,'web',name)));return;}res.writeHead(404);res.end();});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));let browser;try{browser=await chromium.launch();const page=await browser.newPage();await page.goto('http://127.0.0.1:'+server.address().port,{waitUntil:'networkidle'});const link=page.getByText('Retry download',{exact:true});const rect=await link.boundingBox();assert.ok(rect);const sample=await link.evaluate(el=>({pointerEvents:getComputedStyle(el).pointerEvents,html:el.outerHTML}));await page.mouse.click(rect.x+rect.width/2,rect.y+rect.height/2);sample.clicks=await page.evaluate(()=>window.clicks);await page.screenshot({path:path.join(out,'missing-retry.png'),fullPage:true});fs.writeFileSync(path.join(out,'result.json'),JSON.stringify(sample,null,2));console.log(JSON.stringify(sample));assert.equal(sample.clicks,1,'visible Retry download must be pointer-activatable');}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}})().catch(e=>{console.error(e.message);process.exitCode=1});
